  "output_head": "//! `Bot`: a chat member that posts through the bot API (`POST /rooms/:room_id/:bot_key/messages`)
//! instead of signing in. Not in Rails Campfire: a bot is a `users` row with the `bot` role (so it
//! joins rooms and authors messages like anyone), plus a row in this app's own `bots` table (see
//! `schema::ADDITIONS`) with who created it and the token its key carries, and maybe a
//! [`Webhook`].

use rusqlite::{Connection, params};

use crate::database::Tx;
use crate::error::{Error, Errors, OptionalExt, Result};
use crate::models::account::DEFAULT_BOTS_PER_MEMBER;
use crate::models::room::grant_open_rooms_to;
use crate::models::user::user_columns;
use crate::models::{Account, NewUser, PasswordDigest, Role, User, UserChanges, Webhook};
use crate::sql::{self, CachedStatements, columns, query_all, query_one};
use crate::time::Timestamp;

/// How many characters of `SecureRandom.alphanumeric` a token has: about 143 bits.
pub const TOKEN_LENGTH: usize = 24;

#[derive(Debug, Clone, PartialEq)]
pub struct Bot {
    pub id: i64,
    /// The bot's own `users` row.
    pub user_id: i64,
    /// Who set the bot up: they (and administrators) can see its key, edit and delete it.
    pub creator_id: i64,
    pub token: String,
    pub created_at: Timestamp,
    pub updated_at: Timestamp,
}

/// Attributes for [`Bot::create`].
#[derive(Debug, Clone)]
pub struct NewBot {
    pub name: String,
    pub creator_id: i64,
    /// A bot never signs in, but `users.password_digest` is `NOT NULL` and Rails'
    /// `has_secure_password` wants one present: the digest of a random password nobody knows.
    pub password_digest: PasswordDigest,
}

columns! {
    Bot, "bots", bot_columns {
        id: "id",
        user_id: "user_id",
        creator_id: "creator_id",
        token: "token",
        created_at: "created_at",
        updated_at: "updated_at",
    }
}

/// The active bot users and their `bots` rows, joined (`User::SELECT`'s columns first).
const SELECT_ACTIVE: &str = concat!(
    "SELECT ",
    user_columns!(),
    ", ",
    bot_columns!(),
    r#" FROM "users" INNER JOIN "bots" ON "bots"."user_id" = "users"."id" WHERE "users"."status" = 0 AND "users"."role" = 2"#
);

impl Bot {
    fn user_and_bot(row: &rusqlite::Row<'_>) -> rusqlite::Result<(User, Bot)> {
        Ok((User::from_row(row)?, Bot::from_row_at(row, User::COLUMNS.len())?))
    }

    // Finders

    /// The `bots` row of a bot's user, whatever the user's status.
    pub fn find_by_user_id(conn: &Connection, user_id: i64) -> Result<Option<Self>> {
        query_one(conn, concat!("SELECT ", bot_columns!(), r#" FROM "bots" WHERE "bots"."user_id" = ? LIMIT 1"#), [user_id], Self::from_row)
    }

    /// The active bots `user` may manage, by name: everyone's for an administrator, otherwise the
    /// ones they created.
    pub fn manageable_by(conn: &Connection, user: &User) -> Result<Vec<(User, Bot)>> {
        if user.is_administrator() {
            query_all(conn, &format!("{SELECT_ACTIVE} ORDER BY LOWER(\"users\".\"name\")"), [], Self::user_and_bot)
        } else {
            let sql = format!(r#"{SELECT_ACTIVE} AND "bots"."creator_id" = ? ORDER BY LOWER("users"."name")"#);
            query_all(conn, &sql, [user.id], Self::user_and_bot)
        }
    }

    /// One of [`Bot::manageable_by`], by the bot's user id; `RecordNotFound` for anyone else's.
    pub fn find_manageable_by(conn: &Connection, user: &User, bot_user_id: i64) -> Result<(User, Bot)> {
        let found = query_one(conn, &format!(r#"{SELECT_ACTIVE} AND "users"."id" = ? LIMIT 1"#), [bot_user_id], Self::user_and_bot)?;
        found.filter(|(_, bot)| user.can_administer(Some(bot.creator_id), false)).or_not_found("User")
    }

    /// The active bot a bot key (`"<user id>-<token>"`, see [`Bot::key`]) belongs to. The token is
    /// compared in constant time, so a response's timing doesn't reveal how much of it matched.
    pub fn authenticate(conn: &Connection, key: &str) -> Result<Option<User>> {
        let Some((id, token)) = key.split_once('-') else { return Ok(None) };
        let Some(id) = id.parse::<i64>().ok().filter(|_| id.bytes().all(|b| b.is_ascii_digit())) else { return Ok(None) };
        let found = query_one(conn, &format!(r#"{SELECT_ACTIVE} AND "users"."id" = ? LIMIT 1"#), [id], Self::user_and_bot)?;
        Ok(found.filter(|(_, bot)| rails_compat::secure_compare(bot.token.as_bytes(), token.as_bytes())).map(|(user, _)| user))
    }

    // Limits

    /// How many active bots `user` created. Deleted bots (no `bots` row, a deactivated user) don't
    /// count.
    pub fn count_created_by(conn: &Connection, user_id: i64) -> Result<i64> {
        sql::count(
            conn,
            r#"SELECT COUNT(*) FROM "bots" INNER JOIN "users" ON "users"."id" = "bots"."user_id" WHERE "users"."status" = 0 AND "users"."role" = 2 AND "bots"."creator_id" = ?"#,
            [user_id],
        )
    }

    /// How many bots `user` may have: the account's `bots_per_member`, or `None` (n",
  "output_tail": "database::Tx;
use crate::error::{Errors, Result};
use crate::models::bot::bot_columns;
use crate::models::user::user_columns;
use crate::models::{Bot, User};
use crate::sql::{CachedStatements, columns, placeholders, query_all, query_one};
use crate::time::Timestamp;

#[derive(Debug, Clone, PartialEq)]
pub struct Webhook {
    pub id: i64,
    /// The bot's `bots` row (not its user).
    pub bot_id: i64,
    /// An absolute `http://` or `https://` URL.
    pub url: String,
    pub created_at: Timestamp,
    pub updated_at: Timestamp,
}

columns! {
    Webhook, "bot_webhooks", webhook_columns {
        id: "id",
        bot_id: "bot_id",
        url: "url",
        created_at: "created_at",
        updated_at: "updated_at",
    }
}

/// The active bot users with webhooks, their `bots` rows and webhooks, joined.
const SELECT_OF_ACTIVE_BOTS: &str = concat!(
    "SELECT ",
    user_columns!(),
    ", ",
    bot_columns!(),
    ", ",
    webhook_columns!(),
    r#" FROM "users" INNER JOIN "bots" ON "bots"."user_id" = "users"."id""#,
    r#" INNER JOIN "bot_webhooks" ON "bot_webhooks"."bot_id" = "bots"."id""#,
    r#" WHERE "users"."status" = 0 AND "users"."role" = 2"#
);

impl Webhook {
    // Finders

    pub fn find_by_bot_id(conn: &Connection, bot_id: i64) -> Result<Option<Self>> {
        let sql = concat!("SELECT ", webhook_columns!(), r#" FROM "bot_webhooks" WHERE "bot_webhooks"."bot_id" = ? LIMIT 1"#);
        query_one(conn, sql, [bot_id], Self::from_row)
    }

    /// The active bots among `user_ids` that have a webhook, with their `bots` rows and webhooks,
    /// in the order of `user_ids`.
    pub fn of_active_bots(conn: &Connection, user_ids: &[i64]) -> Result<Vec<(User, Bot, Webhook)>> {
        if user_ids.is_empty() {
            return Ok(Vec::new());
        }
        let sql = format!(r#"{SELECT_OF_ACTIVE_BOTS} AND "users"."id" IN ({})"#, placeholders(user_ids.len()));
        let mut found = query_all(conn, &sql, rusqlite::params_from_iter(user_ids), |row| {
            let bot_at = User::COLUMNS.len();
            Ok((User::from_row(row)?, Bot::from_row_at(row, bot_at)?, Webhook::from_row_at(row, bot_at + Bot::COLUMNS.len())?))
        })?;
        found.sort_by_key(|(user, _, _)| user_ids.iter().position(|id| *id == user.id));
        Ok(found)
    }

    // Writing

    /// Sets the bot's webhook to `url` (surrounding whitespace stripped), or removes it when that's
    /// blank.
    pub fn assign(tx: &mut Tx<'_>, bot_id: i64, url: &str) -> Result<Option<Self>> {
        let url = url.trim();
        if url.is_empty() {
            Self::destroy_for(tx, bot_id)?;
            return Ok(None);
        }
        validate_url(url)?;
        let now = tx.now();
        let webhook = tx.conn().query_row_cached(
            concat!(
                r#"INSERT INTO "bot_webhooks" ("bot_id", "url", "created_at", "updated_at") VALUES (?, ?, ?, ?)"#,
                r#" ON CONFLICT ("bot_id") DO UPDATE SET "url" = excluded."url", "updated_at" = excluded."updated_at""#,
                " RETURNING ",
                webhook_columns!()
            ),
            params![bot_id, url, now, now],
            Self::from_row,
        )?;
        Ok(Some(webhook))
    }

    /// Removes the bot's webhook, if it has one.
    pub fn destroy_for(tx: &mut Tx<'_>, bot_id: i64) -> Result<()> {
        tx.conn().execute_cached(r#"DELETE FROM "bot_webhooks" WHERE "bot_webhooks"."bot_id" = ?"#, [bot_id])?;
        Ok(())
    }
}

/// An absolute `http://` or `https://` URL with a host, and no whitespace.
fn validate_url(url: &str) -> Result<()> {
    let mut errors = Errors::default();
    if !valid_url(url) {
        errors.add("webhook_url", "must be an http:// or https:// URL");
    }
    errors.into_result()
}

fn valid_url(url: &str) -> bool {
    if url.chars().any(|c| c.is_whitespace() || c.is_control()) {
        return false;
    }
    let Some((scheme, rest)) = url.split_once("://") else { return false };
    let authority = rest.split(['/', '?', '#']).next().unwrap_or("");
    let host = authority.rsplit_once('@').map_or(authority, |(_, host)| host);
    (scheme.eq_ignore_ascii_case("http") || scheme.eq_ignore_ascii_case("https")) && !host.is_empty() && !host.starts_with(':')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn urls_must_be_absolute_http_urls() {
        let valid = ["http://localhost:4567/hook", "https://bots.example.com/campfire?x=1", "HTTPS://example.com", "http://[::1]:80/"];
        for url in valid {
            assert!(valid_url(url), "{url}");
        }
        let invalid = ["example.com/hook", "ftp://example.com", "http://", "http:///path", "http://:80/", "http://a b.com", "data://x"];
        for url in invalid {
            assert!(!valid_url(url), "{url}");
        }
    }
}
