#[tokio::test]
async fn html_answers_are_posted_and_no_content_posts_nothing() {
    let server = FakeServer::start(vec![
        Route::new("POST", "*", "/html", 200).header("Content-Type", "text/html").body("<p>Build <strong>green</strong></p>"),
        Route::new("POST", "*", "/quiet", 204),
    ])
    .await;
    let app = TestApp::boot().await;
    let mut david = app.david();
    let (html_bot, _) = create_bot_in_hq_with_webhook(&app, &mut david, "Html Bot", &format!("http://{}/html", server.addr)).await;
    let (quiet_bot, _) = create_bot_in_hq_with_webhook(&app, &mut david, "Quiet Bot", &format!("http://{}/quiet", server.addr)).await;

    post_message(&mut david, HQ, &mentioning(&app, quiet_bot.id, "anything?")).await;
    assert_eq!(received(&server, 1).await.len(), 1);
    post_message(&mut david, HQ, &mentioning(&app, html_bot.id, "status")).await;
    let answer = message_by(&app, HQ, html_bot.id).await.expect("the HTML bot's answer");
    assert!(rich_text_body(&app, answer.id).await.contains("<strong>green</strong>"));
    let quiet_id = quiet_bot.id;
    assert!(app.db().read(move |conn| Message::by_creator(conn, quiet_id)).await.unwrap().is_empty(), "204 posts nothing");

    // Unmentioned bots hear nothing.
    post_message(&mut david, HQ, "<p>No bots here</p>").await;
    tokio::time::sleep(Duration::from_millis(200)).await;
    assert_eq!(server.received().len(), 2);
}

